// DEV_RIO_102 Experiment Design — dry-run
// design/REVENUE_LOOP_MVP.md / DATA_MODEL.md(experiments) 準拠。変更変数は必ず1つ。
const i = $input.first().json;
return [{ json: {
  experiment_id: i.experiment_id ?? 'exp-001',
  audience_id: i.audience_id ?? 'aud-store-owner',
  offer_id: i.offer_id ?? 'P-BRAIN-01',
  angle: i.angle ?? 'AIで雑務を週3時間削減',
  channel: i.channel ?? 'threads',
  variable_changed: i.variable_changed ?? 'hook',
  success_condition: i.success_condition ?? 'note遷移≥50 かつ Brain遷移≥5（14日）',
  stop_condition: i.stop_condition ?? '≥1000表示 or ≥50クリックで明確な負',
  min_data: i.min_data ?? '≥1000表示 or ≥50クリック',
  judge_by: i.judge_by ?? null
} }];

// バリデーション: 変更変数が1つか、必須項目が揃っているか。
const o = $input.first().json;
const required = ['experiment_id','audience_id','offer_id','channel','variable_changed','success_condition','stop_condition'];
const missing = required.filter(k => !o[k]);
const singleVariable = typeof o.variable_changed === 'string' && !o.variable_changed.includes(',');
const valid = missing.length === 0 && singleVariable;
return [{ json: { ...o, valid, missing, singleVariable, state: valid ? 'QA_REVIEW' : 'FAILED_RETRYABLE',
  note: valid ? 'dry-run OK。experiments へ登録候補。' : `不備: ${missing.join(',') || '変更変数が複数'}` } }];
